package com.db.driver

import java.util.concurrent.atomic.{AtomicBoolean, AtomicInteger, AtomicReference}
import java.util.concurrent.{ConcurrentLinkedQueue, CountDownLatch, TimeUnit}
import scala.collection.mutable
import scala.concurrent.{Future, Promise, ExecutionContext}
import scala.util.{Try, Success, Failure}

case class Connection(id: Int, valid: Boolean = true)
case class Query(sql: String, promise: Promise[ResultSet])
case class ResultSet(rows: List[Map[String, Any]])

class ConnectionPool(maxSize: Int)(implicit ec: ExecutionContext) {
  private val pool = new ConcurrentLinkedQueue[Connection]()
  private val activeCount = new AtomicInteger(0)
  private val shuttingDown = new AtomicBoolean(false)
  private val drainLatch = new CountDownLatch(1)
  private val pendingQueries = new ConcurrentLinkedQueue[Query]()
  private val connectionIdGen = new AtomicInteger(0)
  private val shutdownPhase = new AtomicInteger(0) // 0=running, 1=draining, 2=closed

  // Initialize pool
  (1 to maxSize).foreach { _ =>
    pool.offer(Connection(connectionIdGen.incrementAndGet()))
  }

  def execute(sql: String): Future[ResultSet] = {
    val promise = Promise[ResultSet]()
    val query = Query(sql, promise)

    if (shuttingDown.get()) {
      // During shutdown, we still allow queries that were "in-flight"
      // This is the grace period behavior
      enqueueForDrain(query)
    } else {
      processQuery(query)
    }

    promise.future
  }

  private def processQuery(query: Query): Unit = {
    val conn = acquireConnection()
    conn match {
      case Some(c) =>
        try {
          val result = executeOnConnection(c, query.sql)
          query.promise.success(result)
        } catch {
          case e: Exception => query.promise.failure(e)
        } finally {
          releaseConnection(c)
        }
      case None =>
        pendingQueries.offer(query)
    }
  }

  private def enqueueForDrain(query: Query): Unit = {
    // Check phase BEFORE adding to queue - atomic rejection
    if (shutdownPhase.get() >= 2) {
      query.promise.failure(new IllegalStateException("Pool closed"))
      return
    }
    pendingQueries.offer(query)
    // Double-check after enqueue to handle race with shutdown completing
    if (shutdownPhase.get() >= 2) {
      val removed = pendingQueries.remove(query)
      if (removed) {
        query.promise.failure(new IllegalStateException("Pool closed"))
      }
    }
  }

  private def acquireConnection(): Option[Connection] = {
    val conn = pool.poll()
    if (conn != null) {
      activeCount.incrementAndGet()
      Some(conn)
    } else None
  }

  private def releaseConnection(conn: Connection): Unit = {
    val count = activeCount.decrementAndGet()
    if (shuttingDown.get()) {
      // Don't return to pool during shutdown - destroy it
      destroyConnection(conn)
      if (count == 0 && pendingQueries.isEmpty) {
        drainLatch.countDown()
      }
    } else {
      pool.offer(conn)
      // Process any pending query
      val pending = pendingQueries.poll()
      if (pending != null) {
        processQuery(pending)
      }
    }
  }

  def shutdown(gracePeriodMs: Long): Future[Unit] = {
    val shutdownPromise = Promise[Unit]()

    if (!shuttingDown.compareAndSet(false, true)) {
      shutdownPromise.failure(new IllegalStateException("Already shutting down"))
      return shutdownPromise.future
    }

    shutdownPhase.set(1) // draining

    Future {
      // Drain pending queries with remaining connections
      drainPendingQueries()

      // Wait for active queries to complete
      val drained = drainLatch.await(gracePeriodMs, TimeUnit.MILLISECONDS)

      // CRITICAL: Set phase to closed
      shutdownPhase.set(2)

      if (!drained) {
        // Force-fail remaining queries
        forceClearPending()
      }

      // Destroy remaining pooled connections
      destroyAllPooled()

      shutdownPromise.success(())
    }

    shutdownPromise.future
  }

  private def drainPendingQueries(): Unit = {
    var query = pendingQueries.poll()
    while (query != null) {
      val conn = pool.poll()
      if (conn != null) {
        activeCount.incrementAndGet()
        try {
          val result = executeOnConnection(conn, query.sql)
          query.promise.success(result)
        } catch {
          case e: Exception => query.promise.failure(e)
        } finally {
          activeCount.decrementAndGet()
          destroyConnection(conn)
        }
      } else {
        // No connections available, fail the query
        query.promise.failure(new IllegalStateException("No connections during drain"))
      }
      query = pendingQueries.poll()
    }
  }

  private def forceClearPending(): Unit = {
    var query = pendingQueries.poll()
    while (query != null) {
      query.promise.tryFailure(new IllegalStateException("Shutdown timeout"))
      query = pendingQueries.poll()
    }
  }

  private def destroyAllPooled(): Unit = {
    var conn = pool.poll()
    while (conn != null) {
      destroyConnection(conn)
      conn = pool.poll()
    }
  }

  private def executeOnConnection(conn: Connection, sql: String): ResultSet = {
    if (!conn.valid) throw new IllegalStateException("Connection invalidated")
    // Simulate query execution
    Thread.sleep(10)
    ResultSet(List(Map("result" -> 1)))
  }

  private def destroyConnection(conn: Connection): Unit = {
    // Invalidate and close the underlying socket
    // After this, any use of conn is a use-after-free equivalent
  }
}

object GracefulShutdownDriver {
  implicit val ec: ExecutionContext = ExecutionContext.global

  def createPool(size: Int): ConnectionPool = new ConnectionPool(size)
}
